-- Additive City Map V1 schema. Existing character data is untouched.
create or replace function nd_private.map_point(p jsonb) returns boolean language plpgsql immutable set search_path='' as $$begin return jsonb_typeof(p)='object' and jsonb_typeof(p->'x')='number' and jsonb_typeof(p->'y')='number' and (p->>'x')::numeric between 0 and 1 and (p->>'y')::numeric between 0 and 1; exception when others then return false;end$$;
create or replace function nd_private.map_polygons(p jsonb) returns boolean language plpgsql immutable set search_path='' as $$declare poly jsonb;pt jsonb;begin if jsonb_typeof(p)<>'array' or jsonb_array_length(p)>20 then return false;end if;for poly in select value from jsonb_array_elements(p) loop if jsonb_typeof(poly)<>'array' or jsonb_array_length(poly)<3 or jsonb_array_length(poly)>500 then return false;end if;for pt in select value from jsonb_array_elements(poly) loop if not nd_private.map_point(pt) then return false;end if;end loop;end loop;return true;exception when others then return false;end$$;
create or replace function nd_private.map_image(p text) returns boolean language sql immutable set search_path='' as $$select p is null or (length(p)<=700000 and (p ~ '^https://[^[:space:]]+$' or p ~ '^data:image/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$'))$$;
create or replace function nd_private.map_can_campaign(target uuid) returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and exists(select 1 from public.campaign_characters cc join public.characters c on c.id=cc.character_id where cc.campaign_id=target and (c.owner_id=auth.uid() or nd_private.can_access(c.id,false)))$$;
revoke all on function nd_private.map_can_campaign(uuid) from public,anon;grant execute on function nd_private.map_can_campaign(uuid) to authenticated;
create policy map_member_campaign on public.campaigns for select to authenticated using(nd_private.map_can_campaign(id));
create policy map_member_assignment on public.campaign_characters for select to authenticated using(exists(select 1 from public.characters c where c.id=character_id and (c.owner_id=(select auth.uid()) or nd_private.can_access(c.id,false))));
create table public.map_districts(id text primary key check(id ~ '^[a-z0-9-]{1,80}$'),name text not null check(length(name) between 1 and 200),short_description text not null default '' check(length(short_description)<=2000),description text not null default '' check(length(description)<=20000),color text not null check(color ~ '^#[A-Fa-f0-9]{6}$'),polygons jsonb not null default '[]' check(nd_private.map_polygons(polygons)),image text check(nd_private.map_image(image)),security text not null default '' check(length(security)<=200),control text not null default '' check(length(control)<=200),activity text not null default '' check(length(activity)<=300),visibility text not null default 'public' check(visibility in ('public','hidden')),contour_status text not null default 'draft' check(contour_status in ('draft','confirmed')),revision integer not null default 1 check(revision>0));
create table public.map_locations(id uuid primary key default gen_random_uuid(),name text not null check(length(name) between 1 and 200),category text not null check(category in ('shop','club','clinic','contact','corporation','industrial','warehouse','shelter','info','special','danger','quest','transport','docks','research','service')),district_id text references public.map_districts(id) on delete set null,position jsonb not null check(nd_private.map_point(position)),short_description text not null default '' check(length(short_description)<=2000),description text not null default '' check(length(description)<=20000),details text not null default '' check(length(details)<=10000),npc text not null default '' check(length(npc)<=2000),image text check(nd_private.map_image(image)),visibility text not null default 'public' check(visibility in ('public','campaign','hidden')),campaign_id uuid references public.campaigns(id) on delete cascade,locked boolean not null default false,revision integer not null default 1 check(revision>0),check(visibility<>'campaign' or campaign_id is not null));
create table public.map_campaign_state(id uuid primary key references public.campaigns(id) on delete cascade,position jsonb check(position is null or nd_private.map_point(position)),label text not null default 'Группа' check(length(label)<=200),revision integer not null default 1 check(revision>0));
create table public.map_route_edges(id uuid primary key default gen_random_uuid(),campaign_id uuid references public.campaigns(id) on delete cascade,aq integer not null check(abs(aq)<=100),ar integer not null check(abs(ar)<=100),bq integer not null check(abs(bq)<=100),br integer not null check(abs(br)<=100),car boolean not null default true,foot boolean not null default true,blocked boolean not null default false,crossing boolean not null default false,cost numeric not null default 1 check(cost between 1 and 20),revision integer not null default 1 check(revision>0),check(greatest(abs(aq-bq),abs(ar-br),abs(aq+ar-bq-br))=1));
create table public.map_settings(id text primary key check(id='global'),data jsonb not null check(jsonb_typeof(data)='object' and (data->>'crossingHours')::numeric between 1 and 20 and (data->>'carHours')::numeric between .1 and 10 and (data->>'footHours')::numeric between 1 and 20 and (data->>'scaleFactor')::numeric between .2 and 3 and jsonb_typeof(data->'routingConfirmed')='boolean'),revision integer not null default 1 check(revision>0));
create index on public.map_locations(campaign_id);create index on public.map_locations(district_id);create index on public.map_route_edges(campaign_id);
alter table public.map_districts enable row level security;alter table public.map_locations enable row level security;alter table public.map_campaign_state enable row level security;alter table public.map_route_edges enable row level security;alter table public.map_settings enable row level security;
revoke all on public.map_districts,public.map_locations,public.map_campaign_state,public.map_route_edges,public.map_settings from public,anon,authenticated;
grant select,insert,update,delete on public.map_districts,public.map_locations,public.map_campaign_state,public.map_route_edges,public.map_settings to authenticated;
create policy map_master on public.map_districts for all to authenticated using((select public.is_master())) with check((select public.is_master()));
create policy map_read on public.map_districts for select to authenticated using(visibility='public');
create policy map_master on public.map_locations for all to authenticated using((select public.is_master())) with check((select public.is_master()));
create policy map_read on public.map_locations for select to authenticated using(visibility<>'hidden' and (visibility='public' or campaign_id is not null) and (campaign_id is null or nd_private.map_can_campaign(campaign_id)));
create policy map_master on public.map_campaign_state for all to authenticated using((select public.is_master())) with check((select public.is_master()));
create policy map_read on public.map_campaign_state for select to authenticated using(nd_private.map_can_campaign(id));
create policy map_master on public.map_route_edges for all to authenticated using((select public.is_master())) with check((select public.is_master()));
create policy map_read on public.map_route_edges for select to authenticated using(campaign_id is null or nd_private.map_can_campaign(campaign_id));
create policy map_master on public.map_settings for all to authenticated using((select public.is_master())) with check((select public.is_master()));
create policy map_read on public.map_settings for select to authenticated using(true);
revoke all on function nd_private.map_point(jsonb),nd_private.map_polygons(jsonb),nd_private.map_image(text) from public,anon;grant execute on function nd_private.map_point(jsonb),nd_private.map_polygons(jsonb),nd_private.map_image(text) to authenticated;
create function public.map_import_geometry(rows jsonb) returns void language plpgsql security invoker set search_path='' as $$declare row jsonb;affected integer;begin if not public.is_master() then raise exception 'Master access required' using errcode='42501';end if;if jsonb_typeof(rows)<>'array' or jsonb_array_length(rows)>50 then raise exception 'Invalid geometry import';end if;for row in select value from jsonb_array_elements(rows) loop if not nd_private.map_polygons(row->'polygons') then raise exception 'Invalid polygon';end if;update public.map_districts set polygons=row->'polygons',contour_status='draft',revision=revision+1 where id=row->>'id' and revision=(row->>'revision')::integer;get diagnostics affected=row_count;if affected<>1 then raise exception 'Geometry changed in another session';end if;end loop;end$$;
revoke all on function public.map_import_geometry(jsonb) from public,anon;grant execute on function public.map_import_geometry(jsonb) to authenticated;
